class Configuration {
  static #instance;

  constructor() {
    this.environment = 'production';
  }

  static getInstance() {
    if (!Configuration.#instance) {
      Configuration.#instance = new Configuration();
    }
    return Configuration.#instance;
  }
}

const configA = Configuration.getInstance();
configA.environment = 'development';

const configB = Configuration.getInstance();
console.log(configB.environment); // 'development'
console.log(configA === configB);  // true

class NotificationFactory {
  static create(type) {
    if (type === 'email') return new EmailNotification();
    if (type === 'sms') return new SmsNotification();
    throw new Error('Type inconnu');
  }
}

const notif = NotificationFactory.create('email');
notif.send('Bienvenue !');

class Subject {
  #observers = [];
  subscribe(fn) { this.#observers.push(fn); }
  notify(data) { this.#observers.forEach((fn) => fn(data)); }
}

const prixPoisson = new Subject();
prixPoisson.subscribe((p) => console.log('Nouveau prix :', p));
prixPoisson.notify(1500);

const marcheVide = new Subject();
marcheVide.notify('rien à signaler'); // aucun abonné : forEach ne fait rien, pas d'erreur levée

const strategies = {
  carte: (montant) => montant * 1.02,
  wave: (montant) => montant * 1.01,
  especes: (montant) => montant,
};

function calculerTotal(montant, mode) {
  return strategies[mode](montant);
}

function calculerTotalSecurise(montant, mode) {
  if (!strategies[mode]) throw new Error(`Mode de paiement inconnu : ${mode}`);
  return strategies[mode](montant);
}

// API externe imposée, format différent
class AncienService { recupererDonnees() { return { d: [1,2,3] }; } }

// Adapter vers l'interface attendue par notre app
class ServiceAdapter {
  #service = new AncienService();
  getData() { return this.#service.recupererDonnees().d; }
}

class AncienServiceInstable { recupererDonnees() { return null; } }
class ServiceAdapterRobuste {
  #service = new AncienServiceInstable();
  getData() { return this.#service.recupererDonnees()?.d ?? []; }
}

function avecLog(fn) {
  return (...args) => {
    console.log('Appel avec', args);
    return fn(...args);
  };
}

const additionner = (a, b) => a + b;
const additionnerAvecLog = avecLog(additionner);
additionnerAvecLog(2, 3); // log puis 5

class PizzaBuilder {
  #pizza = { garnitures: [] };
  ajouterGarniture(g) { this.#pizza.garnitures.push(g); return this; }
  taille(t) { this.#pizza.taille = t; return this; }
  build() { return this.#pizza; }
}

const pizza = new PizzaBuilder()
  .taille('L')
  .ajouterGarniture('thiof')
  .ajouterGarniture('oignons')
  .build();

const pizzaSansTaille = new PizzaBuilder()
  .ajouterGarniture('mafe')
  .build();
